def design(ns, recipe):
    from itertools import combinations_with_replacement
    g = []
    names = []

    def add(z, n):
        g.append(np.asarray(z).reshape(len(ns['a']), -1))
        names.extend(n)
    for term in recipe.split():
        if len(term) == 1:
            add(ns[term], [term + str(i) for i in range(4)])
            continue
        if term[0] == '@':
            add((ns[term[1]] * ns[term[2]]).sum(1), [term])
            continue
        (a, b) = term
        (z, w) = (ns[a], ns[b])
        ij = list(combinations_with_replacement(range(4), 2)) if a == b else [(i, j) for i in range(4) for j in range(4)]
        add(np.column_stack([z[:, i] * w[:, j] for (i, j) in ij]), [f'{a}{i}{b}{j}' for (i, j) in ij])
    return (D(*g), ['1'] + names)

def _even(x, rate):
    squared = x * x
    return _design(x, squared / np.sqrt(1 + rate * squared))

def _fit_operator(u, v, design, bounds):
    from scipy.optimize import minimize_scalar

    def loss(rate):
        g = design(u, rate)
        return np.sum((g @ _least_squares(g, v) - v) ** 2)
    rate = minimize_scalar(loss, bounds=bounds, method='bounded').x
    coefficients = _least_squares(design(u, rate), v)
    return lambda x: design(x, rate) @ coefficients

def _ridge(g, target, penalty):
    n = len(target)
    training = g[:n]
    normal = training.T @ training + penalty * np.eye(g.shape[1])
    normal[0, 0] -= penalty
    return g[n:] @ np.linalg.solve(normal, training.T @ target)
